/**
 * Reversible escaping, wrapper-tag neutralization, and byte-budgeted truncation
 * for model-facing text.
 *
 * THIS FILE IS THE SOURCE OF TRUTH. Copies in plugins are generated by
 * `tools/sync-shared-code.mjs` and must stay byte-identical.
 *
 * ASCII only: see the workspace AGENTS.md encoding rule.
 */

import { Buffer } from 'node:buffer'

/** The default ceiling for one tool's model-visible text, in escaped bytes. */
export const DEFAULT_TEXT_BUDGET = 64 * 1024

/**
 * Neutralize XML wrapper tags (`<content>`, `</content>`, `<path>`, `<type>`,
 * `<query>`) so untrusted document text or paths cannot close a tool envelope.
 * Only escapes the opening `<` of matching wrapper tags; ordinary text is kept.
 * @param {string} value
 * @returns {string}
 */
export function neutralizeWrapperTags(value) {
  return String(value).replace(/<(\/?)(content|path|type|query)>/gi, '\\u003c$1$2>')
}

/**
 * Escape one physical source line so it cannot forge rows or close wrappers.
 * Backslashes are doubled to keep escapes reversible.
 * @param {string} value - one physical source line, without its terminator.
 * @returns {string}
 */
export function encodeSourceLine(value) {
  let out = ''
  for (const char of String(value)) {
    const code = char.codePointAt(0)
    if (char === '\\') { out += '\\\\'; continue }
    if (char === '\t') { out += '\\t'; continue }
    if (code === undefined) continue
    if (code < 0x20 || code === 0x7f || code === 0x85 || code === 0x2028 || code === 0x2029) {
      out += `\\u${code.toString(16).padStart(4, '0')}`
      continue
    }
    out += char
  }
  return neutralizeWrapperTags(out)
}

/**
 * Quote a path or heading with JSON escaping plus Unicode line separators.
 * @param {string} value
 * @returns {string}
 */
export function quote(value) {
  return JSON.stringify(String(value)).replace(
    /[\u0085\u2028\u2029]/g,
    (char) => `\\u${char.codePointAt(0).toString(16).padStart(4, '0')}`,
  )
}

/**
 * The escaped byte cost of a text body as the host JSON-encodes content blocks.
 * @param {string} text
 * @returns {number}
 */
export function escapedBytes(text) {
  return Buffer.byteLength(JSON.stringify([{ type: 'text', text }]), 'utf8')
    - Buffer.byteLength(JSON.stringify([{ type: 'text', text: '' }]), 'utf8')
}

/**
 * Truncate a body to an escaped-byte budget, appending a recovery notice.
 * Guarantees `measure(result) <= budget` even when the custom notice is long,
 * and never splits a UTF-16 surrogate pair at the boundary.
 *
 * @param {string} text
 * @param {object} [options]
 * @param {number} [options.budget] - 512..1048576 bytes.
 * @param {string} [options.reason]
 * @param {string} [options.recovery]
 * @param {(text: string) => number} [options.measure]
 * @returns {string}
 */
export function capText(text, options = {}) {
  const budget = options.budget ?? DEFAULT_TEXT_BUDGET
  if (!Number.isSafeInteger(budget) || budget < 512 || budget > 1024 * 1024) {
    throw new RangeError('text budget must be 512..1048576 bytes')
  }
  const measure = options.measure ?? escapedBytes
  if (measure(text) <= budget) return text

  const reason = options.reason ?? 'output-budget'
  const recovery = options.recovery ?? 'Repeat the same call with a smaller limit; do not advance past undisplayed content.'
  let notice = `\n[Notice: Display incomplete. TruncatedBy: ${reason}. ${recovery}]`

  if (measure(notice) > budget) {
    let lo = 0
    let hi = notice.length
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2)
      if (measure(notice.slice(0, mid)) <= budget) lo = mid
      else hi = mid - 1
    }
    const tail = lo > 0 ? notice.charCodeAt(lo - 1) : 0
    if (tail >= 0xd800 && tail <= 0xdbff) lo -= 1
    return notice.slice(0, lo)
  }

  let low = 0
  let high = text.length
  while (low < high) {
    const middle = Math.ceil((low + high) / 2)
    if (measure(text.slice(0, middle) + notice) <= budget) low = middle
    else high = middle - 1
  }
  const last = low > 0 ? text.charCodeAt(low - 1) : 0
  if (last >= 0xd800 && last <= 0xdbff) low -= 1
  return text.slice(0, low) + notice
}
